        raise ValueError("Day number must be an integer between 1 and 7.")

    days_of_week = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]

    if day_number == 1:
        return days_of_week[0]
    elif day_number == 2:
        return days_of_week[1]
    elif day_number == 3:
        return days_of_week[2]
    elif day_number == 4:
        return days_of_week[3]
    elif day_number == 5:
        return days_of_week[4]
    elif day_number == 6:
        return days_of_week[5]
    elif day_number == 7:
        return days_of_week[6]
    else:
        raise ValueError("Invalid day number.")


